mapper.select:
select m.*
from t_movie m

  join t_movie_type_rel r on r.movie_id = m.id and r.type_id = #{typeId}


  and m.status != 2
  
    and m.year = #{year}
  
  
    and m.region = #{region}
  
  
    and m.name like concat('%', #{keyword}, '%')
  

order by m.status asc, m.release_date desc, m.id desc

mapper.insert:
insert into t_movie(
  name, name_en, poster_url, region, year, language, release_date, duration_min,
  intro, trailer_json, status, total_box_office, rating_avg, rating_count
) values (
  #{name}, #{nameEn}, #{posterUrl}, #{region}, #{year}, #{language}, #{releaseDate}, #{durationMin},
  #{intro}, #{trailerJson}, #{status}, #{totalBoxOffice}, #{ratingAvg}, #{ratingCount}
)

mapper.update:
update t_movie
set total_box_office = ifnull(total_box_office, 0) + #{delta}, updated_time=now()
where id=#{movieId}

update t_movie
set rating_avg = #{avg}, rating_count = #{cnt}, updated_time=now()
where id=#{movieId}
